text:
{{
  (() => {
    const statut = Get_Commande_ById.data?.[0]?.Statut || '';
    let emoji = '📌';
    if (statut.includes('COMPLÈTE') || statut.includes('COMPLETE')) emoji = '✅';
    else if (statut.includes('Action requise')) emoji = '⚠️';
    else if (statut.includes('attente')) emoji = '⏳';
    else if (statut.includes('COMMANDER')) emoji = '🛒';
    else if (statut.includes('COMMANDE')) emoji = '🚚';
    else if (statut.includes('BL')) emoji = '📝';
    else if (statut.includes('FACTUR')) emoji = '🟣';

    return `  ${emoji} ${statut}`;
  })()
}}

textColor:
{{
  (() => {
    const statut = (Get_Commande_ById.data[0]?.Statut || "").toUpperCase().trim();
    switch (statut) {
      case 'PIECE A COMMANDER':
      case 'PIÈCE À COMMANDER': return '#dc2626'; // Rouge
      case 'PIECE EN COMMANDE':
      case 'PIÈCE EN COMMANDE': return '#16a34a'; // Vert
      case 'DEVIS': return '#9333ea'; // Violet
      case 'A REMONTER':
      case 'À REMONTER': return '#ea580c'; // Orange / Rouge
      case 'À DIAGNOSTIQUER': return '#2563eb'; // Bleu
      case 'PRÊT': return '#15803d'; // Vert foncé
      default: return '#0f172a'; // Couleur texte sombre par défaut
    }
  })()
}}
